+import com.fasterxml.jackson.core.util.JsonParserDelegate;
+
+import java.io.IOException;
+
+/**
+ * Rejects JSON payloads that contain empty field names.
+ */
+public class NonEmptyFieldNameJsonParser extends JsonParserDelegate
+{
+  public NonEmptyFieldNameJsonParser(JsonParser delegate)
+  {
+    super(delegate);
+  }
+
+  @Override
+  public JsonToken nextToken() throws IOException
+  {
+    JsonToken token = super.nextToken();
+    if (token == JsonToken.FIELD_NAME) {
+      verifyFieldName(super.getCurrentName());
+    }
+    return token;
+  }
+
+  @Override
+  public String getCurrentName() throws IOException
+  {
+    String name = super.getCurrentName();
+    verifyFieldName(name);
+    return name;
+  }
+
+  private void verifyFieldName(String name) throws JsonParseException
+  {
+    if (name != null && name.isEmpty()) {
+      throw new JsonParseException(this, "Empty field names are not allowed");
+    }
+  }
+}
